function swalConfirm(title="Bạn có chắc chắn muốn thực thi?",confirmText="Có",cancelText="Không"){return swal.fire({title:title,text:"",icon:"warning",showCancelButton:!0,confirmButtonText:confirmText,cancelButtonText:cancelText}).then(function(n){return!!n.value})}
function swalError(title="Thao tác thất bại!"){return swal.fire({title:title,text:"",icon:"error"})}
function swalSuccess(title="Thao tác thành công!"){return swal.fire({title:title,text:"",icon:"success"})}
function swalLoading(title="Đang thực thi..."){return swal.fire({title:title,text:"",icon:"info"})}
function swalInput(title,defaultValue="",inputType="number"){return new Promise(i=>{Swal.fire({title:title,inputValue:defaultValue,input:inputType,icon:"info",showCancelButton:!0,confirmButtonText:"Đồng ý",cancelButtonText:"Không"}).then(t=>i(t.value||!1))})}
function swalBlock(title="Đang get link...",icon="info"){Swal.fire({title:title,icon:icon,html:"",allowOutsideClick:!1,showCancelButton:!1,showConfirmButton:!1})}
function swalClose(){Swal.close();}
function swalTimeOut(title, icon = "success", timeout = 3000, confirmButtomText = 'Đã đọc', cancelButtonText = '', autoResolve = false) { return new Promise(function (resolve) { const randomId = Math.random().toString().substring(2); let idBtnConfirm = 'btn_confirm_' + randomId; let idBtnCancel = 'btn_cancel_' + randomId; var timeInterval; Swal.fire({ title: title, icon: icon, html: ` <button id="${idBtnConfirm}" class="btn btn-success" disabled onclick="swal.close()"> ${confirmButtomText} (<span>${Math.floor(timeout / 1000)}</span>) </button> ${cancelButtonText ? `<button id="${idBtnCancel}" class="btn btn-danger">${cancelButtonText}</button>` : ''} `, allowOutsideClick: false, showCancelButton: false, showConfirmButton: false, didOpen: () => { $('#' + idBtnCancel).click(function () { swal.close(); return resolve(false); }); timeInterval = setInterval(function () { (timeout -= 100); $(`#${idBtnConfirm} span`).html(Math.ceil(timeout / 1000)); if (timeout <= 100) { if (autoResolve) { swal.close(); return resolve(true); } $('#' + idBtnConfirm).prop("disabled", false).html(confirmButtomText); clearInterval(timeInterval); $('#' + idBtnConfirm).click(function () { return resolve(true); }); } }, 100); }, }).then(() => { if (timeInterval) clearInterval(timeInterval); }) }); }

function swalNotifyTimeOut(content, timeout = 3000) {
    return new Promise(function (resolve) {
        const randomId = Math.random().toString().substring(2);
        let idBtnConfirm = 'btn_confirm_' + randomId;
        var timeInterval;
        Swal.fire({
            title: '',
            icon: '',
            html: ` 
<div class="x-notify">
 <div class="x-notify-header">
 Thông báo ngày ${moment().format('DD/MM')}
 </div>
 <div class="x-notify-separator"></div>
 <div class="x-notify-content">
${renderText(content).replace(/\n/g, '<br />')}
 </div>
</div>
 <button id="${idBtnConfirm}" class="btn btn-success" disabled onclick="swal.close()"> Đã đọc (<span>${Math.floor(timeout / 1000)}</span>) </button>`,
            allowOutsideClick: false,
            showCancelButton: false,
            showConfirmButton: false,
            didOpen: () => {
                timeInterval = setInterval(function () {
                    (timeout -= 100);
                    $(`#${idBtnConfirm} span`).html(Math.ceil(timeout / 1000));
                    if (timeout <= 100) {
                        $('#' + idBtnConfirm).prop("disabled", false).html('Đã đọc');
                        clearInterval(timeInterval);
                        $('#' + idBtnConfirm).click(function () {
                            return resolve(true);
                        });
                    }
                }, 100);
            },
        }).then(() => {
            if (timeInterval) clearInterval(timeInterval);
        })
    });
}

